def cZeroRestrict (e : ι ↪ κ) : C₀(κ, X) →L[𝕜] C₀(ι, X) :=
  LinearMap.mkContinuous
    { toFun := cZeroRead e
      map_add' := by intros; rfl
      map_smul' := by intros; rfl }
    1 (fun x => by simpa using norm_cZeroRead_le e x)

